  "……风停了。前面，就是墨水的源头。": "...ลมหยุดแล้ว ข้างหน้าคือต้นกำเนิดของหมึก",
  "……哥哥。姐姐。你们终于来了。": "...พี่ชาย พี่สาว ในที่สุดพวกพี่ก็มาแล้ว",
  "……轰。打不动了。": "...ตูม ตีไม่เข้าเลย",
  "……轰。对不起，是我下的雨。": "...ตูม ขอโทษนะ ฝนนั่นฉันเป็นคนทำให้ตกเอง",
  "……脚步，停了。": "...เสียงฝีเท้าหยุดแล้ว",
