  "……可我停不下来。请你们，把它们都打完，好吗？": "...แต่ฉันหยุดไม่ได้ ช่วยกำจัดพวกมันให้หมดทีได้ไหม",
  "……裂缝，合上了。安静了。": "...รอยแยกปิดแล้ว เงียบสงบแล้ว",
  "……墨水味的。": "...มีกลิ่นหมึก",
  "……那个壳，不会是我们的城墙吧？": "...เปลือกนั่น ไม่ใช่กำแพงของเราใช่ไหม",
  "……你真的，不讨厌我吗？": "...เธอไม่เกลียดฉันจริง ๆ เหรอ",
  "……森林里的树告诉我，有个小卫兵一路守到了这里。我是守林人Rowan。": "...ต้นไม้ในป่าบอกว่ามีทหารยามตัวน้อยคอยเฝ้าสู้มาจนถึงที่นี่ ฉันคือ Rowan ผู้พิทักษ์ป่า",
  "……我记得你。我记得这座城墙。可我不记得，我为什么要来。": "...ฉันจำเธอได้ จำกำแพงนี้ได้ แต่จำไม่ได้ว่าทำไมถึงมาที่นี่",
  "……谢谢。重复得……好累。": "...ขอบคุณนะ ทำอะไรซ้ำ ๆ... เหนื่อยจัง",
