  "北境维京": "ไวกิ้งเหนือ",
  "贝贝": "เบเบ้",
  "贝贝把每一个贝壳都记在小本子上。她说，城墙是她见过的最大的\"壳\"，可惜不能分给任何人。": "เบเบ้จดเปลือกหอยทุกชิ้นลงในสมุดเล่มเล็ก เธอบอกว่ากำแพงเป็น \"เปลือก\" ที่ใหญ่ที่สุดที่เคยเห็น แต่น่าเสียดายที่แบ่งให้ใครไม่ได้",
  "贝贝合壳时几乎打不动，张壳时会吐珍珠，但也最怕疼。抓住张壳的时候放雷霆一击和箭雨！": "ตอนเปลือกปิด เบเบ้แทบตีไม่เข้า ตอนเปลือกเปิดจะพ่นไข่มุก แต่ก็กลัวเจ็บที่สุด ตอนเปลือกเปิดให้ใช้ฟ้าผ่าและห่าธนู!",
  "贝贝着急了：开合得更快了！": "เบเบ้ร้อนรนแล้ว: เปลือกเปิดปิดเร็วขึ้น!",
