  "被打死时射出尖刺，扎伤周围的怪物。等它挤进怪堆里再打！走到城墙时会先扎一下。": "เมื่อถูกฆ่าจะยิงหนามออกมาทำร้ายมอนสเตอร์รอบ ๆ รอให้มันเข้าไปอยู่กลางฝูงก่อนค่อยฆ่า! ตอนถึงกำแพงมันจะแทงกำแพงหนึ่งทีก่อน",
