  "被月光侵蚀的绿团团：血量高，不被打的时候会自己回血。": "ก้อนเขียวที่ถูกแสงจันทร์กัดกร่อน: เลือดเยอะ และฟื้นเลือดเองเมื่อไม่โดนตี",
  "被震晕了！": "มึนไปเลย!",
