  "本法老在研究新口味的饼干。这次只放了三百年。": "ฟาโรห์ผู้นี้กำลังวิจัยคุกกี้รสใหม่ รอบนี้อบแค่สามร้อยปีเอง",
  "本关城墙第一次被打倒时，立刻复活并回复 60% 最大血量（只有一次）": "ครั้งแรกที่กำแพงล้มในด่านนี้ จะฟื้นคืนชีพทันทีพร้อมเลือด 60% ของสูงสุด (ครั้งเดียว)",
