  "本关铜币收益 +60%，并立刻获得一笔铜币": "รายได้เหรียญทองแดงด่านนี้ +60% และได้เหรียญทองแดงก้อนหนึ่งทันที",
  "本女王的城堡……怎么这么热？谁把炉火点起来的？": "ปราสาทของราชินีผู้นี้... ทำไมร้อนอย่างนี้ ใครจุดเตาไฟน่ะ?",
  "本体现身！伤害 +50%": "ร่างจริงปรากฏ! ดาเมจ +50%",
