  "绷带球不怕物理攻击。去商店用银币解锁「魔法杖」，或者带上雷霆一击、灼烧！": "ก้อนผ้าพันแผลไม่กลัวการโจมตีกายภาพ ไปปลดล็อก \"ไม้เท้าเวท\" ที่ร้านด้วยเหรียญเงิน หรือพกฟ้าผ่ากับเผาไหม้ไปด้วย!",
