  "别怕，它们只是被一股奇怪的黑墨水弄得脾气很坏。守住城墙，就是守住大家。": "อย่ากลัวนะ พวกมันแค่อารมณ์เสียเพราะหมึกดำแปลก ๆ ปกป้องกำแพงก็คือปกป้องทุกคน",
