  "冰棍大叔说，霜霜女王把墨水冻成了一面大镜子，镜子里能看到一道红色的裂缝。": "ลุงไอติมบอกว่าราชินีฟรอสตี้แช่หมึกจนเป็นกระจกบานใหญ่ ในกระจกมองเห็นรอยแยกสีแดง",
