  "冰晶精灵活着时英雄的攻速会变慢。它们躲在远处，用箭雨、雷霆一击顺手清掉最划算。": "ตราบที่เงือกคริสตัลน้ำแข็งยังมีชีวิต ฮีโร่จะโจมตีช้าลง พวกมันซ่อนอยู่ไกล ๆ ใช้ห่าธนูกับฟ้าผ่ากวาดทีเดียวคุ้มที่สุด",
