  "波波的触手。只要还有 3 条以上，波波就很难打动。": "หนวดของโบโบ้ ตราบที่ยังเหลือ 3 เส้นขึ้นไป โบโบ้จะตีเข้ายากมาก",
  "波波的吸盘在吸收力量！快打掉触手！": "ปุ่มดูดของโบโบ้กำลังดูดพลัง! รีบตัดหนวดเร็ว!",
  "波波有触手护身：先打掉触手（\"威胁优先\"和\"Boss 优先\"都会这么做）。血量低于 60% 后触手还会给它回血，最后它会卷起大漩涡！": "โบโบ้มีหนวดคุ้มกัน: ตัดหนวดก่อน (\"ภัยคุกคามก่อน\" และ \"บอสก่อน\" ทำแบบนี้ทั้งคู่) เมื่อเลือดต่ำกว่า 60% หนวดจะฟื้นเลือดให้มันด้วย และท้ายสุดมันจะก่อวังวนยักษ์!",
