  "不等清场，每 14 秒来一波": "ไม่รอเคลียร์สนาม มาทุก 14 วินาทีหนึ่งระลอก",
  "不管是谁，铁雪人、铁狼……它们都披着铁甲朝我们走过来了。": "ไม่ว่าจะเป็นใคร มนุษย์หิมะเหล็ก หมาป่าเหล็ก... พวกมันสวมเกราะเหล็กเดินมาหาเราแล้ว",
  "不靠技能": "ไม่พึ่งสกิล",
