  "不是它们本人，是\"回声\"：从那道裂缝里传出来的、被混沌染成蓝紫色的影子。它们会一直往城墙走。": "ไม่ใช่ตัวจริงของพวกเขา แต่เป็น \"เสียงสะท้อน\": เงาจากรอยแยกนั้นที่ความโกลาหลย้อมเป็นสีม่วงน้ำเงิน พวกมันจะเดินตรงไปที่กำแพงเรื่อย ๆ",
  "不是我！是你自己的闹钟……我是说，你的小兵们。": "ไม่ใช่ฉัน! นาฬิกาปลุกของเธอเองต่างหาก... หมายถึงทหารตัวน้อยของเธอน่ะ",
