  "存档文字不正确，请检查是否完整复制": "ข้อความเซฟไม่ถูกต้อง โปรดตรวจว่าคัดลอกมาครบ",
  "存档已导入": "นำเข้าเซฟแล้ว",
  "存档已清空": "ล้างเซฟแล้ว",
  "打败的 Boss 都搬到了小镇上。点一点，听听它们现在过得怎么样。": "บอสที่เธอเอาชนะได้ย้ายมาอยู่ในเมืองกันหมดแล้ว แตะดูสิว่าตอนนี้พวกมันเป็นอย่างไรบ้าง",
  "打败了咕噜大王！它其实是草原上最勤快的清道夫。黑风是从沙漠吹来的，我要出发了。": "เอาชนะราชากูลูได้แล้ว! จริง ๆ แล้วเขาเป็นคนกวาดทุ่งหญ้าที่ขยันที่สุด ลมดำพัดมาจากทะเลทราย ฉันต้องออกเดินทางแล้ว",
  "打败了这一层的全部妖怪。": "เอาชนะมอนสเตอร์ทั้งหมดในชั้นนี้แล้ว",
  "打断 Boss": "ขัดจังหวะบอส",
  "打断 Boss 至少 2 次，并通关": "ขัดจังหวะบอสอย่างน้อย 2 ครั้งและผ่านด่าน",
