  "打断大师": "เซียนขัดจังหวะ",
  "打断专家": "ผู้เชี่ยวชาญขัดจังหวะ",
  "大 Boss": "บอสใหญ่",
  "大 Boss。暴风雪降低攻速，冰封城墙让它无法修复，残血时召唤小冰龙。": "บอสใหญ่ พายุหิมะลดความเร็วโจมตี กำแพงที่ถูกแช่แข็งซ่อมไม่ได้ และเมื่อเลือดน้อยจะเรียกมังกรน้ำแข็งตัวเล็ก",
  "大 Boss。冰冻、暴风雪、冰墙，比原来更冷。": "บอสใหญ่ เขตน้ำแข็ง พายุหิมะ กำแพงน้ำแข็ง หนาวกว่าเดิม",
  "大 Boss。毒雾腐蚀城墙，把小怪煮成强化版，残血时倒翻大锅制造毒池。": "บอสใหญ่ หมอกพิษกัดกร่อนกำแพง ต้มลูกกระจ๊อกให้แกร่งขึ้น และเมื่อเลือดน้อยจะคว่ำหม้อใหญ่สร้างบ่อพิษ",
  "大 Boss。会刮沙暴、召唤木乃伊并给它们回血，残血时展开金字塔护盾——护盾只怕魔法。": "บอสใหญ่ ก่อพายุทราย เรียกมัมมี่และฟื้นเลือดให้พวกมัน เมื่อเลือดน้อยจะกางโล่พีระมิด ซึ่งกลัวแค่เวทมนตร์",
  "大 Boss。会召唤小兵；血量低于 60% 后发动野猪冲锋，预警时集中火力可以打断。": "บอสใหญ่ เรียกลูกน้องได้ เมื่อเลือดต่ำกว่า 60% จะพุ่งชนแบบหมูป่า ตอนเตือนให้รวมยิงเพื่อขัดจังหวะได้",
  "大 Boss。沙暴、召唤、治疗、护盾，三个阶段，比原来难缠得多。": "บอสใหญ่ พายุทราย เรียกลูกน้อง รักษา โล่ สามช่วง เล่นยากกว่าเดิมมาก",
  "大个子白毛怪，物理护甲很高。": "ตัวใหญ่ขนขาว เกราะกายภาพสูงมาก",
  "大锅倾倒！毒池让怪物加速！": "หม้อใหญ่คว่ำแล้ว! บ่อพิษทำให้มอนสเตอร์เร็วขึ้น!",
  "大漩涡！触手全部长回来了，所有怪物都变快了！": "วังวนยักษ์! หนวดงอกกลับมาครบ มอนสเตอร์ทุกตัวเร็วขึ้น!",
