  "单局连击达到 30（1.2 秒内连续击败怪物）": "ทำคอมโบให้ถึง 30 ในรอบเดียว (ฆ่ามอนสเตอร์ต่อเนื่องห่างกันไม่เกิน 1.2 วิ)",
