  "第六章 Boss。爱生气的大雷云：召唤雷团子和彩虹鸟、蓄力落雷、最后掀起暴风雨。": "บอสบทที่ 6 เมฆฟ้าร้องตัวใหญ่ขี้โมโห: เรียกก้อนฟ้าร้องกับนกสายรุ้ง สะสมพลังฟ้าผ่า และท้ายสุดก่อพายุฝน",
  "第七章 Boss。章鱼大王：触手护身、吸盘回血、最后卷起大漩涡。先打触手！": "บอสบทที่ 7 ราชาปลาหมึกยักษ์: หนวดคุ้มกัน ปุ่มดูดฟื้นเลือด และท้ายสุดก่อวังวนยักษ์ ตัดหนวดก่อน!",
