  "钢雪怪怕魔法，熔铁傀儡怕物理——换武器还是靠技能，自己选。": "เยติเหล็กกล้ากลัวเวท หุ่นเหล็กหลอมกลัวกายภาพ จะเปลี่ยนอาวุธหรือใช้สกิลก็เลือกเอาเอง",
  "钢雪怪怕魔法、盾龟还会保护身边的怪物——先拆掉盾龟，再用魔法对付钢雪怪。": "เยติเหล็กกล้ากลัวเวท และเต่าโล่ปกป้องมอนสเตอร์รอบตัว จัดการเต่าโล่ก่อน แล้วใช้เวทสู้เยติเหล็กกล้า",
