  "哥哥！我也要守城墙！我的铃铛一响，小怪都会吓一跳！": "พี่ชาย! ฉันก็อยากปกป้องกำแพง! พอกระดิ่งฉันดัง มอนสเตอร์ตัวเล็กจะตกใจกันหมด!",
  "个人纪录：{0} 波 · 击败 {1} 只": "สถิติส่วนตัว: ระลอก {0} · ฆ่าได้ {1} ตัว",
  "根据本关的怪物自动选择武器、技能和道具。": "เลือกอาวุธ สกิล และไอเทมให้อัตโนมัติตามมอนสเตอร์ของด่านนี้",
  "更多武器：在「装备」页的「武器」分类里解锁": "อาวุธเพิ่มเติม: ปลดล็อกได้ในหมวด \"อาวุธ\" ของหน้า \"อุปกรณ์\"",
  "更麻烦的是，它们听说陆地上有一个\"又大又结实的壳\"，正排着队过来搬家——": "ที่ยุ่งยากกว่านั้น พวกมันได้ยินว่าบนบกมี \"เปลือกใหญ่แข็งแรง\" กำลังเข้าแถวมาย้ายบ้านกัน—",
