  "可是波波大王不会听的。他有八条腿，海里没有一个壳装得下他，他已经看上你们的城墙好几天了。": "แต่ราชาโบโบ้ไม่ฟังหรอก เขามีแปดขา ไม่มีเปลือกไหนในทะเลใส่เขาได้ และเขาจ้องกำแพงของพวกเธอมาหลายวันแล้ว",
  "可是雷雷不会信的。它是云端最爱生气的那朵云，彩虹被弄脏以后，它已经气得打了三天的雷。": "แต่ครืนครืนไม่เชื่อหรอก มันเป็นเมฆที่ขี้โมโหที่สุดบนฟ้า ตั้งแต่สายรุ้งเลอะ มันโกรธจนฟ้าร้องมาสามวันแล้ว",
  "可它们明明都和好了呀，怎么又来了？": "แต่พวกมันคืนดีกันแล้วนี่นา ทำไมกลับมาอีก?",
  "可这是大家的家呀！": "แต่นี่คือบ้านของทุกคนนะ!",
  "空格暂停，F 切换 2 倍速，N 提前召唤，T 切换目标优先级。": "เว้นวรรคเพื่อหยุด F สลับเร็ว 2 เท่า N เรียกระลอกถัดไปก่อน T สลับลำดับเป้าหมาย",
  "空袭": "โจมตีทางอากาศ",
  "空袭！被混沌染红的霜龙，和一群会扔火球的小鬼。": "โจมตีทางอากาศ! มังกรน้ำแข็งที่ความโกลาหลย้อมเป็นสีแดง กับฝูงเด็กซนที่ขว้างลูกไฟ",
  "空袭！提灯鬼躲在后面不停回血——先把它找出来。": "โจมตีทางอากาศ! ผีถือตะเกียงซ่อนอยู่ข้างหลังฟื้นเลือดไม่หยุด หามันให้เจอก่อน",
  "空袭！天上的怪物很多，地上还有盾龟护送的小队——别只盯着天上。": "โจมตีทางอากาศ! มอนสเตอร์บนฟ้าเยอะมาก บนพื้นยังมีหน่วยที่เต่าโล่คุ้มกัน อย่ามองแต่ฟ้า",
  "空袭！虚空气球落地时会放出四个哥布林小兵。": "โจมตีทางอากาศ! บอลลูนความว่างเปล่าเมื่อลงพื้นจะปล่อยก็อบลินลูกกระจ๊อกสี่ตัว",
  "空袭关，而且冰晶精灵很多。「飞行优先」加连发弩或雷电法球！": "ด่านโจมตีทางอากาศ และมีเงือกคริสตัลน้ำแข็งเยอะ \"บินก่อน\" บวกหน้าไม้ยิงรัวหรือลูกแก้วสายฟ้า!",
  "空袭关，小恶魔会在远处扔火球。「威胁优先」或「飞行优先」都试试看！": "ด่านโจมตีทางอากาศ ปีศาจจิ๋วจะขว้างลูกไฟจากไกล ๆ ลอง \"ภัยคุกคามก่อน\" หรือ \"บินก่อน\" ดู!",
  "空袭关！蝙蝠会换道，范围攻击比瞄准更可靠。": "ด่านโจมตีทางอากาศ! ค้างคาวสลับเลน การโจมตีวงกว้างเชื่อถือได้กว่าการเล็ง",
  "空袭关！试试把目标优先级切换为「飞行优先」，或者换上连发弩。": "ด่านโจมตีทางอากาศ! ลองสลับลำดับเป้าหมายเป็น \"บินก่อน\" หรือเปลี่ยนไปใช้หน้าไม้ยิงรัว",
  "空袭关！秃鹫飞得很快。连发弩和「飞行优先」是好选择。": "ด่านโจมตีทางอากาศ! แร้งบินเร็ว หน้าไม้ยิงรัวกับ \"บินก่อน\" เป็นตัวเลือกที่ดี",
  "空中马戏团": "ละครสัตว์บนฟ้า",
  "骷髅驾驶的小推车，高速冲撞，撞墙伤害很高。": "รถเข็นเล็กที่โครงกระดูกขับ พุ่งชนด้วยความเร็วสูง ชนกำแพงเจ็บมาก",
  "骷髅卫兵": "ทหารโครงกระดูก",
  "骷髅卫兵举着厚重的骨盾，正面几乎打不动——回旋镖和箭雨能绕到背后。": "ทหารโครงกระดูกถือโล่กระดูกหนา ด้านหน้าแทบตีไม่เข้า บูมเมอแรงกับห่าธนูอ้อมไปด้านหลังได้",
  "骷髅战车": "รถศึกโครงกระดูก",
  "快得看不清的兔子，会换车道，物理攻击有四分之一的几率打空。": "กระต่ายที่เร็วจนมองไม่ทัน สลับเลนได้ การโจมตีกายภาพพลาดหนึ่งในสี่",
