  "雷雷": "ครืนครืน",
  "雷雷开始蓄电了！蓄力时集中火力打断！": "ครืนครืนเริ่มสะสมไฟฟ้าแล้ว! ตอนมันสะสมพลัง รวมยิงขัดจังหวะ!",
  "雷雷其实只是太喜欢那道彩虹了。现在它每次下完雨，都会特意把彩虹挂得高高的。王国的守城卫兵，守住了地上，也守住了天上。": "จริง ๆ ครืนครืนแค่ชอบสายรุ้งนั้นมากเกินไป ตอนนี้ทุกครั้งที่ฝนหยุด มันจะแขวนสายรุ้งให้สูงสวยเป็นพิเศษ ทหารยามของอาณาจักรปกป้องทั้งพื้นดินและท้องฟ้าไว้ได้",
  "雷雷有三个阶段：召唤雷团子和彩虹鸟、蓄力落雷（打断它！）、暴风雨（全场加速，速战速决）。": "ครืนครืนมีสามช่วง: เรียกก้อนฟ้าร้องกับนกสายรุ้ง สะสมพลังฟ้าผ่า (ขัดจังหวะมัน!) และพายุฝน (ทั้งสนามเร็วขึ้น รีบจบให้ไว)",
