  "熔岩怪物不怕魔法，记得带上物理武器。Kael——一定要平安回来。": "มอนสเตอร์ลาวาไม่กลัวเวท อย่าลืมพกอาวุธกายภาพ Kael— กลับมาอย่างปลอดภัยนะ",
  "熔岩怪物不怕魔法，用物理重炮": "มอนสเตอร์ลาวาไม่กลัวเวท ใช้ปืนใหญ่หนักกายภาพ",
