  "三条小路": "สามเส้นทาง",
  "三只一群，从同一条车道高速冲来。": "มาเป็นกลุ่มละสามตัว พุ่งเร็วลงเลนเดียวกัน",
  "森林的守林人，背着一张比他还高的长弓。攻击力 ×1.5、攻速 ×0.73；重箭无视 25% 护甲，并把普通怪物向后推 12 像素。": "ผู้พิทักษ์ป่า แบกธนูยาวที่สูงกว่าตัวเอง ATK ×1.5 ความเร็วโจมตี ×0.73 ธนูหนักทะลุเกราะ 25% และผลักมอนสเตอร์ธรรมดาถอยหลัง 12 พิกเซล",
  "沙暴、召唤、治疗、护盾——三个阶段的胖法老，更硬了。": "พายุทราย เรียกลูกน้อง รักษา โล่ — ฟาโรห์อ้วนสามช่วง แกร่งกว่าเดิม",
