  "沙粒瓶": "ขวดทราย",
  "沙漠？看来事情没有那么简单。Kael，你愿意去看看吗？": "ทะเลทราย? ดูท่าเรื่องจะไม่ง่ายนัก Kael เธอยินดีไปดูไหม?",
  "沙漠的太阳好大。这里的怪物缠着绷带，箭射上去软绵绵的，得想想别的办法。": "แดดทะเลทรายร้อนจัง มอนสเตอร์ที่นี่พันผ้าพันแผล ลูกธนูยิงใส่แล้วนิ่มนิ่ม ต้องคิดวิธีอื่น",
  "沙漠里的木乃伊不怕普通的箭。听说魔法杖能帮上忙，去商店看看吧！": "มัมมี่ในทะเลทรายไม่กลัวธนูธรรมดา ได้ยินว่าไม้เท้าเวทช่วยได้ ไปดูที่ร้านค้าสิ!",
  "沙漠里所有的敌人都来了。先清掉小祭司和仙人掌球！": "ศัตรูทั้งหมดในทะเลทรายมากันแล้ว เคลียร์นักบวชน้อยกับลูกกระบองเพชรก่อน!",
