  "同时持有 5000 铜币": "ถือเหรียญทองแดง 5000 เหรียญพร้อมกัน",
  "同时扔出 2 支：目标车道和相邻车道各一支": "ขว้างพร้อมกัน 2 อัน: เลนเป้าหมายหนึ่ง เลนข้างเคียงหนึ่ง",
  "铜": "ทองแดง",
  "铜币": "เหรียญทองแดง",
  "铜币袋": "ถุงเหรียญทองแดง",
  "铜币档 · 常用": "ระดับเหรียญทองแดง · ใช้บ่อย",
