  "兔冲冲": "กระต่ายพุ่ง",
  "兔冲冲跑得很快。怪物会分散在不同车道上。": "กระต่ายพุ่งวิ่งเร็วมาก มอนสเตอร์จะกระจายไปหลายเลน",
