  "谢谢你们，没有讨厌生气的我。": "ขอบคุณที่ไม่เกลียดฉันตอนที่ฉันโมโห",
  "谢谢你们一直走到这里。": "ขอบคุณที่เดินทางมาถึงที่นี่",
  "谢谢你守住了王国！": "ขอบคุณที่ปกป้องอาณาจักรไว้!",
