  "眨眨眼睛、看看远处，喝口水吧。城墙交给国王爷爷看一会儿。": "กะพริบตา มองไปไกล ๆ แล้วดื่มน้ำสักหน่อย ให้คุณปู่กษัตริย์ดูกำแพงแทนสักพักนะ",
