  "战场变成 4 条车道了。范围攻击和全场技能越来越重要。": "สนามรบกลายเป็น 4 เลนแล้ว การโจมตีวงกว้างและสกิลทั้งสนามยิ่งสำคัญขึ้นเรื่อย ๆ",
