  "战斗暂停中。选一张补给卡，效果持续到本关结束（颜色从低到高：蓝、紫、红、金，越高越强）。按 1 / 2 / 3 也可以选。": "การรบหยุดชั่วคราว เลือกการ์ดเสบียงหนึ่งใบ ผลอยู่จนจบด่าน (สีจากต่ำไปสูง: น้ำเงิน ม่วง แดง ทอง ยิ่งสูงยิ่งแรง) กด 1 / 2 / 3 เพื่อเลือกก็ได้",
  "战斗中点击技能按钮（或按 1 / 2 / 3）释放主动技能，按 Q / W / E / R / Z / X / C 使用道具（每种最多带 3 个，用一个少一个，用完一次要等冷却；道具要先在商店买、再装备）。": "ระหว่างรบ แตะปุ่มสกิล (หรือกด 1 / 2 / 3) เพื่อใช้สกิลแอคทีฟ กด Q / W / E / R / Z / X / C เพื่อใช้ไอเทม (พกได้ชนิดละสูงสุด 3 ชิ้น ใช้ทีละชิ้น ใช้แล้วต้องรอคูลดาวน์ ไอเทมต้องซื้อที่ร้านค้าแล้วสวมก่อน)",
