  "长袍上的星星会自己闪，帽子比人还高一截。": "ดาวบนเสื้อคลุมระยิบระยับเอง หมวกสูงกว่าตัวคนอีกหน่อย",
  "招财坠": "จี้เรียกทรัพย์",
  "沼泽里到处是雾，还有咕呱咕呱的毒蛙。我第一次觉得城墙有点冷。": "ในหนองน้ำมีหมอกไปทั่ว และกบพิษร้องอ๊บ ๆ เป็นครั้งแรกที่ฉันรู้สึกว่ากำแพงเย็นไปนิด",
  "沼泽里的小幽灵几乎不怕物理攻击，毒蛙会在远处吐毒。记得用\"威胁优先\"先打它们！": "ผีน้อยในหนองน้ำแทบไม่กลัวการโจมตีกายภาพ กบพิษจะพ่นพิษจากไกล ๆ อย่าลืมใช้ \"ภัยคุกคามก่อน\" ตีพวกมันก่อน!",
  "沼泽里提着萤火灯的女孩。攻击力 ×0.92、攻速 ×1.05；暗夜里射程不减，物理伤害对灵体 +20%；每第 12 次攻击放出 3 只萤火虫（各造成攻击力 ×0.6 的魔法伤害）。": "เด็กหญิงถือตะเกียงหิ่งห้อยในหนองน้ำ ATK ×0.92 ความเร็วโจมตี ×1.05 กลางคืนระยะยิงไม่ลด ดาเมจกายภาพต่อวิญญาณ +20% ทุกการโจมตีครั้งที่ 12 ปล่อยหิ่งห้อย 3 ตัว (ตัวละดาเมจเวท ATK ×0.6)",
  "沼泽守护者": "ผู้พิทักษ์หนองน้ำ",
  "照明弹": "พลุส่องสว่าง",
  "这不是壳，是城墙！里面住着很多人呢！": "นี่ไม่ใช่เปลือก นี่คือกำแพง! ข้างในมีคนอาศัยอยู่เยอะเลย!",
  "这次我不下雨了。……就下一点点，给新房子洗个澡。": "รอบนี้ฉันจะไม่ทำให้ฝนตก... ตกนิดเดียวพอ เพื่ออาบน้ำให้บ้านหลังใหม่",
  "这句话听起来和以前一模一样。": "ประโยคนี้ฟังเหมือนเมื่อก่อนเป๊ะเลย",
  "这里是裂缝的最深处，连天和地都分不清了。": "ที่นี่คือส่วนลึกที่สุดของรอยแยก ลึกจนแยกไม่ออกว่าฟ้าหรือดิน",
  "这种道具用完了": "ไอเทมนี้หมดแล้ว",
  "镇上的小朋友都叫我汤婆婆，我很喜欢。": "เด็ก ๆ ในเมืองเรียกฉันว่ายายซุป ฉันชอบมาก",
  "镇塔者": "ผู้เฝ้าหอ",
