  "蒸汽工匠": "ช่างไอน้ำ",
  "整关都是暗夜：射程 −30%": "ทั้งด่านเป็นกลางคืนมืดมิด: ระยะยิง −30%",
  "之后可以在「设置」里随时更改。": "ภายหลังเปลี่ยนได้ทุกเมื่อใน \"ตั้งค่า\"",
  "之后每一波开始 6 秒后，天火落下，对全场所有怪造成攻击力 ×4 的魔法伤害": "จากนั้นทุกระลอกเมื่อเริ่ม 6 วิ ไฟจากฟ้าจะตกลงมา สร้างดาเมจเวท ATK ×4 ใส่มอนสเตอร์ทุกตัวในสนาม",
  "知道了": "เข้าใจแล้ว",
  "知道了（空格）": "เข้าใจแล้ว (เว้นวรรค)",
  "只能使用木弓": "ใช้ได้เฉพาะธนูไม้",
  "只要车道变红，我就集中火力打断你的冲锋！": "พอเลนเป็นสีแดง ฉันจะรวมยิงขัดจังหวะการพุ่งชนของเธอ!",
  "至少提前召唤 3 次，并通关": "เรียกก่อนเวลาอย่างน้อย 3 ครั้งและผ่านด่าน",
  "治疗": "รักษา",
  "治疗更多的飞鸟。": "รักษานกบินได้มากขึ้น",
