  "重复通关：通关铜币减半": "เล่นซ้ำ: รางวัลผ่านด่านลดครึ่ง (เหรียญทองแดง)",
  "重甲": "เกราะหนัก",
  "重甲怪、成团的怪、Boss": "มอนสเตอร์เกราะหนัก มอนสเตอร์รวมกลุ่ม บอส",
  "重甲怪、Boss": "มอนสเตอร์เกราะหนัก บอส",
  "重甲突击": "บุกเกราะหนัก",
  "重甲突击！魔法杖、火炮和「穿甲」是这一关的关键。": "บุกเกราะหนัก! ไม้เท้าเวท ปืนใหญ่ และ \"ทะลุเกราะ\" คือกุญแจของด่านนี้",
  "重甲突击！雪怪的物理护甲很高，魔法、火炮和「穿甲」是关键。": "บุกเกราะหนัก! เยติมีเกราะกายภาพสูง เวท ปืนใหญ่ และ \"ทะลุเกราะ\" คือกุญแจ",
  "重箭 · 破甲": "ธนูหนัก · ทำลายเกราะ",
  "重看": "ดูซ้ำ",
  "重新开始": "เริ่มใหม่",
  "朱红的铠甲，头盔上的新月在发光，背上插着一面小旗。": "เกราะสีแดงชาด พระจันทร์เสี้ยวบนหมวกเหล็กเรืองแสง ด้านหลังปักธงเล็ก ๆ",
  "主动技能": "สกิลแอคทีฟ",
  "主动技能（战斗中点击释放）": "สกิลแอคทีฟ (แตะเพื่อใช้ในการรบ)",
  "主动技能槽": "ช่องสกิลแอคทีฟ",
  "主动技能冷却 −{0}%": "คูลดาวน์สกิลแอคทีฟ −{0}%",
  "主动技能冷却 −15%": "คูลดาวน์สกิลแอคทีฟ −15%",
  "主动技能冷却 −20%，并立即刷新所有冷却": "คูลดาวน์สกิลแอคทีฟ −20% และรีเซ็ตคูลดาวน์ทั้งหมดทันที",
  "主动技能冷却 −40%，并立刻刷新全部冷却": "คูลดาวน์สกิลแอคทีฟ −40% และรีเซ็ตคูลดาวน์ทั้งหมดทันที",
  "主动技能冷却 −5%": "คูลดาวน์สกิลแอคทีฟ −5%",
  "主动技能冷却 −8%，无视护甲 +10%": "คูลดาวน์สกิลแอคทีฟ −8% ทะลุเกราะ +10%",
  "煮汤！{0} 只怪物被强化": "ต้มซุป! มอนสเตอร์ {0} ตัวแกร่งขึ้น",
  "助战伙伴": "เพื่อนร่วมรบ",
