  "Boss、重甲怪": "บอส มอนสเตอร์เกราะหนัก",
  "3 道雷，每道攻击力 ×2.5": "ฟ้าผ่า 3 สาย สายละ พลังโจมตี ×2.5",
  "4 道雷，每道攻击力 ×3": "ฟ้าผ่า 4 สาย สายละ พลังโจมตี ×3",
  "5 道雷，每道攻击力 ×3.5，并连锁附近 3 只怪（每只 50%）": "ฟ้าผ่า 5 สาย สายละ พลังโจมตี ×3.5 และสายฟ้าแล่นต่อไปยังมอนสเตอร์ใกล้ ๆ 3 ตัว (ตัวละ 50%)",
  "Lv3 以后每 5 级多劈 1 道雷（最多 15 道），每升一级伤害再强一点、冷却再短一点": "หลัง Lv3 ทุก 5 เลเวลฟ้าผ่าเพิ่ม 1 สาย (สูงสุด 15 สาย) ทุกเลเวลดาเมจแรงขึ้นอีกนิด คูลดาวน์สั้นลงอีกหน่อย",
  "连续劈下 3 道雷霆，每道劈向当前血量最高的怪（尽量各劈不同的怪），造成攻击力 ×2.5 的魔法伤害。": "ฟ้าผ่าลงมาติดกัน 3 สาย แต่ละสายฟาดมอนสเตอร์ที่เลือดเยอะที่สุด (พยายามฟาดคนละตัว) สร้างดาเมจเวทเท่ากับพลังโจมตี ×2.5",
  "丢出会爆炸的炸弹，一颗炸弹伤城墙很重，但很久才丢一颗。": "ขว้างระเบิดที่ระเบิดได้ ลูกเดียวทำกำแพงเจ็บหนักมาก แต่กว่าจะขว้างลูกต่อไปก็นาน",
  "从远处射出冰锥，被冰锥打中的城墙会冻伤，持续受到伤害。": "ยิงเสาน้ำแข็งจากที่ไกล ๆ กำแพงที่โดนจะถูกแช่แข็งจนบาดเจ็บ และเสียหายต่อเนื่อง",
  "冰晶法师": "จอมเวทคริสตัลน้ำแข็ง",
  "力气很大的怪，停在远处抛出大石头，一块砸下去很疼，但出手慢。": "มอนสเตอร์แรงเยอะ ยืนอยู่ไกล ๆ แล้วโยนก้อนหินใหญ่ ก้อนเดียวก็เจ็บมาก แต่ลงมือช้า",
  "哥布林弓手": "ก็อบลินนักธนู",
  "投弹手": "นักขว้างระเบิด",
  "投石怪": "ปีศาจขว้างหิน",
  "站在最远处召来闪电劈向城墙，闪电没有弹道、躲不开，但出手慢。": "ยืนไกลที่สุดแล้วเรียกสายฟ้าฟาดใส่กำแพง สายฟ้าไม่มีวิถีให้หลบ หลบไม่ได้ แต่ลงมือช้า",
  "躲在远处的哥布林，一支接一支地朝城墙射箭，箭又快又准。": "ก็อบลินที่แอบอยู่ไกล ๆ ยิงธนูใส่กำแพงทีละดอกไม่หยุด ธนูทั้งเร็วทั้งแม่น",
  "雷电法师": "จอมเวทสายฟ้า",
