  "风吹麦浪": "ลมพัดรวงข้าวสาลี",
  "出手很快，暴击率 +15%，伤害比木弓还高一点。": "ยิงไว คริติคอล +15% แรงกว่าธนูไม้นิดหน่อย",
  "{0}：通关第 {1} 关解锁": "{0}: ปลดล็อกหลังผ่านด่าน {1}",
  "还有 {0} 把武器可以在「装备」页的「武器」分类里购买": "ยังมีอาวุธอีก {0} ชิ้นที่ซื้อได้ในหมวด \"อาวุธ\" ของหน้าอุปกรณ์",
  "10 秒，每次攻击补 3 箭（70%）": "10 วินาที ทุกครั้งที่โจมตียิงเพิ่ม 3 ดอก (70%)",
  "3 秒，共攻击力 ×3": "3 วินาที พลังโจมตีรวม ×3",
  "4 秒，共攻击力 ×3.6": "4 วินาที พลังโจมตีรวม ×3.6",
  "4 秒，共攻击力 ×4.2，结束时漩涡爆炸，再造成攻击力 ×2.5": "4 วินาที พลังโจมตีรวม ×4.2 เมื่อจบวังวนจะระเบิด สร้างความเสียหายเพิ่มอีกพลังโจมตี ×2.5",
